// The panel's 250-line source cap, read by a gate rather than remembered per pass (SPEC-UI §10).
//
// Every page pass measured this by hand, and two ledger rows drifted for exactly that reason. The rule is
// mechanical, so it gets the same treatment as the dash rule: a tree-wide scan that fails on the file that
// grew, instead of a reviewer noticing it later.
//
// `src/lib/primitives/` is generated by the component layer's CLI and not hand-edited, so it is out of
// scope, the same exception the antislop gate keeps for the same directory.

import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { describe, expect, it } from 'vitest';

const ROOT = process.cwd();
const CAP = 250;

function sources(dir: string): string[] {
	return readdirSync(dir).flatMap((entry) => {
		const path = join(dir, entry);
		if (statSync(path).isDirectory()) return sources(path);
		return /\.(ts|svelte)$/.test(entry) ? [path] : [];
	});
}

const FILES = [...sources(resolve(ROOT, 'src')), ...sources(resolve(ROOT, 'tests'))].filter(
	(file) => !file.includes('/src/lib/primitives/')
);

function lineCount(file: string): number {
	const text = readFileSync(file, 'utf-8');
	const lines = text.split('\n').length;

	return text.endsWith('\n') ? lines - 1 : lines;
}

describe('panel source files', () => {
	it('counts a real tree, so an empty walk cannot pass', () => {
		expect(FILES.length).toBeGreaterThan(300);
	});

	it('stays under the 250-line cap', () => {
		const over = FILES.map((file) => ({
			file: file.slice(ROOT.length + 1),
			lines: lineCount(file)
		}))
			.filter(({ lines }) => lines > CAP)
			.sort((left, right) => right.lines - left.lines)
			.map(({ file, lines }) => `${file}: ${lines}`);

		expect(over, `files over ${CAP} lines:\n${over.join('\n')}`).toEqual([]);
	});
});
